  {
    "alert_id": "EX4_CBZ_DTG_INTERACTION",
    "title": "Carbamazepine lowers dolutegravir levels",
    "message": "Uganda guidelines list carbamazepine as interacting with DTG, decreasing DTG levels by 30-70%, and advise using valproic acid instead. Patient started carbamazepine 400 mg twice daily two weeks ago; viral load rose from <50 to 1,240 copies/mL despite good adherence, consistent with reduced DTG exposure. Carbamazepine toxicity (level 14 mcg/mL, nystagmus, ataxia, tremor) is also present. Poor adherence is an alternative explanation for viraemia but was reportedly good, making the interaction the leading cause.",
    "issue_type": "drug_interaction",
    "severity": "critical",
    "recommended_action": "Stop carbamazepine and switch to valproic acid per guidelines; repeat viral load after 3 months to confirm resuppression.",
    "citations": [
      {"page_number": 49, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p49_c1"}
    ]
  },
  {
    "alert_id": "EX4_CBZ_TOXICITY_HYPONATREMIA",
    "title": "Carbamazepine toxicity with hyponatraemia",
    "message": "Patient has carbamazepine level 14 mcg/mL (therapeutic 4-12) with nystagmus, wide-based gait, and tremor, confirming toxicity. Sodium is 128 mmol/L, and carbamazepine is a recognised cause of hyponatraemia, which can worsen neurological symptoms. The clinician's plan to reduce the dose and repeat the level addresses toxicity, but the hyponatraemia is not addressed. Valproate co-prescription may also contribute to tremor and ataxia. Given the DTG interaction, dose reduction alone leaves the interaction problem unresolved.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Discontinue carbamazepine in favour of valproic acid, correct hyponatraemia, and recheck sodium and neurological symptoms.",
    "citations": [
      {"page_number": 49, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p49_c1"}
    ]
  },
  {
    "alert_id": "EX4_VIREMIA_MANAGEMENT_GAP",
    "title": "Detectable viral load needs enhanced adherence and repeat testing",
    "message": "Guidelines state virological monitoring provides early indication of treatment failure and routine viral load monitoring is annual for adults. Patient's viral load rose from <50 to 1,240 copies/mL. The clinician's plan does not include the recommended response to a detectable viral load, such as enhanced adherence counselling and a repeat viral load in three months before assessing for treatment failure or genotype testing. The carbamazepine-DTG interaction is the likely driver, so removing carbamazepine plus adherence support should be combined.",
    "issue_type": "plan_add",
    "severity": "high",
    "recommended_action": "Provide enhanced adherence counselling, resolve the drug interaction, and repeat viral load in 3 months; consider genotype testing if still detectable.",
    "citations": [
      {"page_number": 12, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p12_c1"},
      {"page_number": 13, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p13_c2"}
    ]
  },
  {
    "alert_id": "EX4_ALT_ELEVATION_TDF_VALPROATE",
    "title": "Mild ALT elevation on TDF and hepatotoxic drugs",
    "message": "Guidelines advise liver function tests for TDF toxicity and monitoring for liver toxicity with interacting drugs. ALT is 68 U/L, mildly elevated, in a patient on TDF, valproate, and carbamazepine, all potentially hepatotoxic. The elevation is modest and could reflect carbamazepine toxicity or recent illness rather than TDF; no baseline ALT is available for comparison. The plan does not include repeat LFTs or further hepatic assessment.",
    "issue_type": "toxicity",
    "severity": "moderate",
    "recommended_action": "Repeat LFTs after stopping carbamazepine; if ALT rises further, evaluate TDF and valproate hepatotoxicity per guidelines.",
    "citations": [
